import { basename } from 'node:path';

const HELP_FLAG_TOKENS = new Set(['-h', '--help']);

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Comma-separated numbers`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}`;
}

export function parseCliArguments(argv, scriptPath) {
  const programName = basename(scriptPath ?? 'test7.mjs');
  let rawA;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      unknown.push(...argv.slice(index));
      break;
    }

    if (HELP_FLAG_TOKENS.has(token)) {
      return {
        kind: 'help',
        programName,
        text: buildHelp(programName),
      };
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || nextToken.startsWith('-')) {
        return {
          kind: 'error',
          code: 2,
          programName,
          text: buildError(programName, 'argument --a: expected one argument'),
        };
      }

      rawA = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      rawA = token.slice('--a='.length);
      continue;
    }

    unknown.push(token);
  }

  if (rawA === undefined) {
    return {
      kind: 'error',
      code: 2,
      programName,
      text: buildError(programName, 'the following arguments are required: --a'),
    };
  }

  if (unknown.length > 0) {
    return {
      kind: 'error',
      code: 2,
      programName,
      text: buildError(programName, `unrecognized arguments: ${unknown.join(' ')}`),
    };
  }

  return {
    kind: 'run',
    programName,
    rawA,
  };
}

