import process from 'node:process';

import { parseCliArguments } from './lib/cli.mjs';
import { bucketize, partition } from './lib/iterutils.mjs';
import { parseCommaSeparatedIntegers, PythonIntegerParseError } from './lib/numbers.mjs';
import { formatPythonTuple, formatPythonValue } from './lib/pyrepr.mjs';

function main() {
  const parsed = parseCliArguments(process.argv.slice(2), process.argv[1]);

  if (parsed.kind === 'help') {
    process.stdout.write(`${parsed.text}\n`);
    return;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(`${parsed.text}\n`);
    process.exitCode = parsed.code;
    return;
  }

  try {
    const numbers = parseCommaSeparatedIntegers(parsed.rawA);
    const result1 = partition(numbers, (value) => value % 2n === 0n);
    process.stdout.write(`${formatPythonTuple(result1)}\n`);

    const result2 = partition(numbers, (value) => value > 0n);
    process.stdout.write(`${formatPythonTuple(result2)}\n`);

    const result3 = bucketize(numbers, (value) => value % 2n === 0n);
    process.stdout.write(`${formatPythonValue(result3)}\n`);

    const result4 = bucketize(numbers, (value) => value > 10n);
    process.stdout.write(`${formatPythonValue(result4)}\n`);
  } catch (error) {
    if (error instanceof PythonIntegerParseError) {
      process.stderr.write(
        `Traceback (most recent call last):\n` +
          `  File "test7.py", line 8, in <module>\n` +
          `${error.name}: ${error.message}\n` +
          `[PYI-${process.pid}:ERROR] Failed to execute script 'test7' due to unhandled exception!\n`,
      );
      process.exitCode = 1;
      return;
    }

    throw error;
  }
}

main();

